<?php
declare(strict_types=1);
namespace BSPDesign;
require_once dirname(__DIR__,2).'/research/_lib/model.php';
const VERSION='2.3.0'; const ROOT='/experiment-design/'; const BASE='https://beyondspacetime.org'; const SCHEMA='beyondspacetime.experiment-design.v1';
function enc($v):string{return \BSPResearch\encode($v);}
function obj($v,string $n):array{return \BSPResearch\object($v,$n);}
function keys(array $v,array $k,string $n):void{\BSPResearch\keys($v,$k,$n);}
function txt($v,int $max,string $name):string{if(!is_string($v)||strlen($v)>$max||trim($v)===''||!preg_match('//u',$v)||preg_match('/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/',$v))throw new \InvalidArgumentException("Invalid $name (required; max $max UTF-8 bytes).");return trim(str_replace(["\r\n","\r"],"\n",$v));}
function num($v,string $name,float $min=0,float $max=1e9):float{if((!is_int($v)&&!is_float($v))||!is_finite((float)$v)||$v<$min||$v>$max)throw new \InvalidArgumentException("Invalid $name.");return (float)$v;}
function model_specs():array{static $out;if($out!==null)return $out;$out=[];foreach(\BSPResearch\models() as $id=>$m){$p=array_column($m['params'],'default','key');$r=$m['kind']==='foundation'?\solve($m['id'],$p):\calc($m['id'],$p);$metrics=[];foreach($r['metrics'] as $i=>$v)if(is_int($v['value'])||is_float($v['value']))$metrics[]=['index'=>$i,'label'=>$v['label'],'unit'=>$v['unit']];$out[$id]=['title'=>$m['title'],'params'=>$m['params'],'metrics'=>$metrics,'evidence'=>$m['evidence'],'url'=>$m['url']];}return $out;}
function template(string $title,string $model,string $variable,int $metric,string $direction,array $settings,array $thresholds,array $notes,array $evidence,array $gates):array{return ['schema'=>SCHEMA,'title'=>$title,'model'=>$model,'variable'=>$variable,'metric'=>$metric,'direction'=>$direction,'cases'=>array_combine(['reference','candidate','negative','positive'],$settings),'criteria'=>['support'=>$thresholds[0],'reject'=>$thresholds[1],'negative_tolerance'=>$thresholds[2],'positive_minimum'=>$thresholds[3]],'uncertainty'=>['numerical'=>1e-8,'calibration'=>0.0,'other'=>0.0],'notes'=>$notes,'evidence'=>$evidence,'gates'=>$gates];}
function notes(string $q,string $h,string $r,string $n,string $p,string $m):array{return ['question'=>$q,'hypothesis'=>$h,'alternative'=>$r,'negative_control'=>$n,'positive_control'=>$p,'measurement_plan'=>$m,'confounders'=>'The chosen solver assumes the specified model and fixed parameters. Its output is synthetic; detector calibration, environmental coupling and model discrepancy are not estimated here.','stopping_rule'=>'Execute exactly the four sealed deterministic cases once; do not tune thresholds after viewing results. Any revised protocol must be sealed separately.'];}
function presets():array{return [
 'photon'=>template('Does a positive gap reduce modeled group speed?','foundation:light-slowing','gap',1,'decrease',[['gap'=>0,'drag'=>.3,'duration'=>5],['gap'=>.2,'drag'=>.3,'duration'=>5],['gap'=>0,'drag'=>.8,'duration'=>5],['gap'=>.5,'drag'=>.3,'duration'=>5]],[.10,.02,.001,.3],notes('Can momentum loss at fixed propagation time discriminate zero-gap and positive-gap conditional histories?','A positive rest-energy gap reduces final modeled group speed at fixed drag and duration.','Zero-gap energy loss need not change group speed. An observed spectral shift alone cannot distinguish mechanisms.','Increase drag in the zero-gap control: speed remains C.','A larger gap at the reference drag should reduce group speed more.','Compare final group speed / C; a physical test would need independently calibrated path length, time of flight, energy and detector response.'),['fixed-gap-drag','ceiling'],['B','C','D']),
 'escape'=>template('Does escape increase the final escaped population?','evidence:escape','ratio',1,'increase',[['ratio'=>0,'duration'=>12],['ratio'=>4,'duration'=>12],['ratio'=>0,'duration'=>20],['ratio'=>8,'duration'=>12]],[.9,.1,.001,.8],notes('Does the Markov escape term permit net escape in this selected-mode model?','At the chosen interaction duration, nonzero escape gives a greater escaped population than the closed reference.','Coherent closed conversion can oscillate without any escaped population. This endpoint does not test continuous individual photon slowing.','Change duration at zero escape: no escaped population.','Nonzero escape at ratio 8 should also yield large escaped population at GT=12.','Measure channel-resolved populations and loss independently; numerical endpoint alone cannot prove the physical reservoir or monotonicity.'),['escape-criterion','escape-verification','phase-match'],['A','C']),
 'timing'=>template('Does fixed transit delay preserve pulse spacing?','foundation:when','period',1,'increase',[['period'=>2,'delay'=>5],['period'=>3,'delay'=>5],['period'=>2,'delay'=>10],['period'=>5,'delay'=>5]],[.9,.1,.001,2],notes('Can a change of emitted spacing be distinguished from a constant transit delay?','Increasing the emission interval increases the received interval by the same amount in the specified stationary-delay model.','A constant delay shifts arrivals without stretching intervals. Moving endpoints or a time-varying channel require separate modeling.','Change only the constant transit delay: arrival spacing must be unchanged.','Use a larger emission interval to verify a known response.','Measure consecutive pulse arrival intervals using a calibrated clock and fixed endpoints; test channel stability independently.'),['moving-endpoints','causal-reach'],['D','E']),
 'distance'=>template('Does ignored attenuation bias inferred size?','foundation:distance-inference','extinction',2,'increase',[['actual'=>1,'extinction'=>0],['actual'=>1,'extinction'=>1],['actual'=>2,'extinction'=>0],['actual'=>1,'extinction'=>2]],[.4,.05,.001,1],notes('How does a signed unmodeled magnitude offset affect inferred/calibrated size?','Positive attenuation ignored by the model increases the inferred/calibrated ratio.','No offset leaves that ratio at one; real astronomical calibration can involve additional variables.','Vary calibrated distance with zero attenuation: the ratio remains one.','A larger positive offset should increase the ratio.','Use the ratio, not absolute distance, as primary endpoint. A physical study needs independent geometric anchors, calibrated flux, extinction and angular size.'),['anchor-lmc','anchor-ngc','optical-map'],['E','F']),
 'geometry'=>template('Does a common translation preserve physical separation?','foundation:where','dx',2,'increase',[['dx'=>3,'dy'=>4,'shift'=>2],['dx'=>6,'dy'=>4,'shift'=>2],['dx'=>3,'dy'=>4,'shift'=>-8],['dx'=>9,'dy'=>4,'shift'=>2]],[2,.1,.001,4],notes('Which changes affect Euclidean separation in the teaching model?','Increasing horizontal separation at fixed vertical separation increases the invariant separation.','A common coordinate translation changes coordinate labels without changing the separation; this does not establish a new theory of geometry.','Change the common origin offset only.','Increase horizontal separation further at fixed vertical separation.','Compare separation computed from calibrated coordinate differences. This is a geometric identity control, not a cosmological observation.'),['charter'],['A'])
];}
function normalized(array $d):array{
 keys($d,['schema','title','model','variable','metric','direction','cases','criteria','uncertainty','notes','evidence','gates'],'protocol');if(($d['schema']??null)!==SCHEMA)throw new \InvalidArgumentException('Unknown protocol schema.');$title=\BSPResearch\words($d['title']??null,160,'Title');$id=$d['model']??null;$models=model_specs();if(!is_string($id)||!isset($models[$id]))throw new \InvalidArgumentException('Unknown model.');$m=$models[$id];$variable=$d['variable']??null;if(!is_string($variable)||!in_array($variable,array_column($m['params'],'key'),true))throw new \InvalidArgumentException('Unknown independent variable.');$metric=$d['metric']??null;$mm=array_column($m['metrics'],null,'index');if(!is_int($metric)||!isset($mm[$metric]))throw new \InvalidArgumentException('Select a numeric primary metric.');$direction=$d['direction']??null;if(!in_array($direction,['increase','decrease'],true))throw new \InvalidArgumentException('Direction must be increase or decrease.');$roles=['reference','candidate','negative','positive'];$cases=obj($d['cases']??null,'Cases');keys($cases,$roles,'cases');$notes=obj($d['notes']??null,'Notes');$nn=[];$fields=['question','hypothesis','alternative','negative_control','positive_control','measurement_plan','confounders','stopping_rule'];keys($notes,$fields,'notes');foreach($fields as $k)$nn[$k]=txt($notes[$k]??null,1500,$k);
 $p=['schema'=>\BSPResearch\SCHEMA,'title'=>$title,'question'=>str_replace(["\n","\r","\t"],' ',substr($nn['question'],0,1500)),'cases'=>[],'evidence'=>$d['evidence']??[]];if(strlen($p['question'])>600)throw new \InvalidArgumentException('Question must not exceed 600 UTF-8 bytes.');foreach($roles as $role)$p['cases'][]=['label'=>ucfirst($role),'model'=>$id,'parameters'=>obj($cases[$role]??null,$role)];$p=\BSPResearch\normalize($p);$cc=array_combine($roles,array_column($p['cases'],'parameters'));$ref=$cc['reference'];foreach(['candidate','positive'] as $role){foreach($ref as $k=>$v)if($k!==$variable&&$cc[$role][$k]!==$v)throw new \InvalidArgumentException("$role must hold all non-primary parameters fixed.");if($cc[$role][$variable]===$ref[$variable])throw new \InvalidArgumentException("$role must change the primary variable.");}if($cc['positive'][$variable]===$cc['candidate'][$variable])throw new \InvalidArgumentException('Positive control must differ from candidate.');if($cc['negative'][$variable]!==$ref[$variable])throw new \InvalidArgumentException('Negative control must keep the primary variable at reference.');
 $c=obj($d['criteria']??null,'Criteria');$u=obj($d['uncertainty']??null,'Uncertainty');$cr=[];$un=[];keys($c,['support','reject','negative_tolerance','positive_minimum'],'criteria');keys($u,['numerical','calibration','other'],'uncertainty');foreach(['support','reject','negative_tolerance','positive_minimum'] as $k)$cr[$k]=num($c[$k]??null,$k);if($cr['support']<=$cr['reject']||$cr['positive_minimum']<=0)throw new \InvalidArgumentException('Support must exceed rejection; positive minimum must exceed zero.');foreach(['numerical','calibration','other'] as $k)$un[$k]=num($u[$k]??null,$k);$g=$d['gates']??null;$all=array_column(\corpus()['gates'],'id');if(!is_array($g)||!array_is_list($g)||count($g)>count($all))throw new \InvalidArgumentException('Invalid gates.');foreach($g as $x)if(!is_string($x)||!in_array($x,$all,true))throw new \InvalidArgumentException('Unknown validation gate.');$g=array_values(array_unique($g));sort($g,SORT_STRING);
 return ['schema'=>SCHEMA,'title'=>$title,'model'=>$id,'variable'=>$variable,'metric'=>$metric,'direction'=>$direction,'cases'=>$cc,'criteria'=>$cr,'uncertainty'=>$un,'notes'=>$nn,'evidence'=>$p['evidence'],'gates'=>$g];
}
function source():array{return ['design_version'=>VERSION,'design_sha256'=>hash_file('sha256',__FILE__),'solver'=>\BSPResearch\provenance()];}
function seal(array $d):array{$p=normalized($d);$s=['schema'=>'beyondspacetime.sealed-protocol.v1','protocol'=>$p,'provenance'=>source(),'notice'=>'Local content fingerprint only; no trusted timestamp, identity or proof of preregistration.'];$s['seal_sha256']=hash('sha256',enc($s));return $s;}
function verified_seal(array $sealed):array{keys($sealed,['schema','protocol','provenance','notice','seal_sha256'],'sealed protocol');if(($sealed['schema']??null)!=='beyondspacetime.sealed-protocol.v1')throw new \InvalidArgumentException('Expected sealed protocol.');$s=seal(obj($sealed['protocol']??null,'Protocol'));if(!is_string($sealed['seal_sha256']??null)||!hash_equals($s['seal_sha256'],$sealed['seal_sha256']))throw new \InvalidArgumentException('Seal mismatch: protocol or installed source has changed. Reseal explicitly.');if(($sealed['provenance']??null)!=$s['provenance']||($sealed['notice']??null)!==$s['notice'])throw new \InvalidArgumentException('Seal provenance or notice mismatch.');return $s;}
function run(array $sealed):array{$s=verified_seal($sealed);$p=$s['protocol'];$plan=['schema'=>\BSPResearch\SCHEMA,'title'=>$p['title'],'question'=>str_replace(["\n","\r","\t"],' ',$p['notes']['question']),'cases'=>[],'evidence'=>$p['evidence']];foreach($p['cases'] as $role=>$params)$plan['cases'][]=['label'=>ucfirst($role),'model'=>$p['model'],'parameters'=>$params];$r=\BSPResearch\evaluate($plan);$m=array_column(model_specs()[$p['model']]['metrics'],null,'index')[$p['metric']];$v=[];foreach($r['runs'] as $i=>$case){$x=$case['result']['metrics'][$p['metric']]??null;if(!$x||$x['label']!==$m['label']||$x['unit']!==$m['unit']||(!is_int($x['value'])&&!is_float($x['value']))||!is_finite((float)$x['value']))throw new \RuntimeException('Primary metric unavailable in a case.');$v[array_keys($p['cases'])[$i]]=(float)$x['value'];}$sign=$p['direction']==='increase'?1:-1;$u=array_sum($p['uncertainty']);$delta=[];foreach($v as $k=>$x){$raw=$x-$v['reference'];$score=$sign*$raw;$delta[$k]=['value'=>$x,'delta'=>$raw,'signed_effect'=>$score,'lower'=>$score-$u,'upper'=>$score+$u];}$c=$p['criteria'];$neg=abs($delta['negative']['delta'])+$u<=$c['negative_tolerance'];$pos=$delta['positive']['lower']>=$c['positive_minimum'];$q=$delta['candidate'];$decision=!($neg&&$pos)?'controls_not_met':($q['lower']>=$c['support']?'criterion_met':($q['upper']<=$c['reject']?'criterion_not_met':'inconclusive'));$out=['schema'=>'beyondspacetime.design-result.v1','sealed'=>$s,'observable'=>$m,'effect_budget'=>$u,'effects'=>$delta,'controls'=>['negative_met'=>$neg,'positive_met'=>$pos],'decision'=>$decision,'interpretation'=>'Decision applies only to the prespecified numerical criterion in the selected model. Bounds are user-declared worst-case additive effect budgets, not statistical confidence intervals. No empirical hypothesis, validation gate or preregistration timestamp is established.','research_result'=>$r];$out['result_sha256']=hash('sha256',enc($out));return $out;}
function catalog():array{return ['schema'=>'beyondspacetime.design-catalog.v1','version'=>VERSION,'models'=>model_specs(),'presets'=>presets(),'gates'=>\corpus()['gates'],'api'=>BASE.ROOT.'api/','scope'=>'Draft and seal four-case numerical protocols; execute with existing solver; no empirical validation or trusted registration.'];}
